<?php require __DIR__.'/../includes/core.php';$u=require_login(['supervisor']);$rows=all("SELECT a.*,m.name module_name,t.name teacher,c.term,s.name session_name FROM assignments a JOIN modules m ON m.id=a.module_id JOIN users t ON t.id=a.subject_id JOIN evaluation_cycles c ON c.id=a.cycle_id JOIN academic_sessions s ON s.id=c.session_id WHERE a.evaluator_id=? AND m.is_active=1 ORDER BY a.id DESC",[$u['id']]);ob_start();?><div class="card"><p>Complete appraisals assigned by the administrator. Submitted results are confidential.</p><div class="tablewrap"><table><tr><th>Teacher</th><th>Module</th><th>Cycle</th><th>Status</th><th>Action</th></tr><?php foreach($rows as $r)echo '<tr><td>'.h($r['teacher']).'</td><td>'.h($r['module_name']).'</td><td>'.h($r['session_name'].' '.$r['term']).'</td><td>'.h($r['status']).'</td><td>'.($r['status']==='submitted'?'Submitted':'<a class="btn" href="'.url('evaluate.php?id='.$r['id']).'">Open form</a>').'</td></tr>';?></table></div></div><?php layout('My performance appraisals',ob_get_clean());